try {
    var saved = JSON.parse(msg.payload);
    if (Array.isArray(saved)) {
        flow.set('db_history', saved);
    }
} catch (e) {
    flow.set('db_history', []);
}
return null;

var data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) { return null; }
}
data.received = new Date().toISOString();
var waktu = data.timestamp || data.received;

var threshold = flow.get('threshold') || 30.0;
var isAlert = parseFloat(data.suhu) > threshold;
data.threshold = threshold;
data.alert = isAlert;
data.alert_message = isAlert ? ('PERINGATAN! Suhu (' + data.suhu + '°C) melewati batas (' + threshold + '°C)!') : 'Normal';

flow.set('lastSensor', data);

// Simpan riwayat persisten (maks 100 record terbaru di atas)
var history = flow.get('db_history') || [];
history.unshift({
    suhu: data.suhu,
    kelembaban: data.kelembaban,
    timestamp: waktu,
    received: data.received
});
if (history.length > 100) history.pop();
flow.set('db_history', history);

// Output 1: WebSocket & Debug
var wsMsg = { payload: JSON.stringify(data) };
// Output 2: Simpan ke file JSON permanen
var fileMsg = { payload: JSON.stringify(history) };
// Output 3: Alert MQTT jika melewati batas
var alertMqttMsg = isAlert ? { topic: 'iot/alert', payload: JSON.stringify(data) } : null;

return [wsMsg, fileMsg, alertMqttMsg];

